import React, { useRef } from 'react';
import { iconDependencies } from './neon-icon';
import { loadingIndicatorDependencies } from './neon-loading-indicator';
import { buildPropsMap, createComponentDependency, toAttribute, 
//useImperativeProps,
useListeners, withNeonWebComponent } from './utils/react-utils';
export const aiChatLauncherDependencies = [
    createComponentDependency('ai-chat-launcher'),
    ...iconDependencies,
    ...loadingIndicatorDependencies
];
function AiChatLauncher(props) {
    const elementRef = useRef();
    // * * * Set Props * * *
    // useImperativeProps<NeonAiChatLauncherElement>(elementRef, {
    //   //propName: propValue
    // });
    // * * * Set Listeners * * *
    useListeners(elementRef, {
        neonValueChange: (event) => {
            if (props.neonValueChange != null) {
                props.neonValueChange(event.detail.value);
            }
        }
    });
    // * * * Set Attributes * * *
    return React.createElement('neon-2_20_1-ai-chat-launcher', buildPropsMap(props, {
        ref: elementRef,
        'data-max-length': toAttribute(props.dataMaxLength),
        'data-placeholder': props.dataPlaceholder,
        'data-disable-speech-to-text': toAttribute(props.dataDisableSpeechToText),
        'data-display-speech-to-text': toAttribute(props.dataDisplaySpeechToText),
        'data-is-loading': toAttribute(props.dataIsLoading),
        'data-is-loading-text': props.dataIsLoadingText,
        'data-error-text': props.dataErrorText,
        'data-aria-label': props.dataAriaLabel,
        'data-input-aria-label': props.dataInputAriaLabel,
        'data-mic-aria-label': props.dataMicAriaLabel,
        'data-submit-aria-label': props.dataSubmitAriaLabel,
        'data-type': props.dataType,
        'onInput': props.onInput
    }), props.children);
}
export const NeonAiChatLauncher = withNeonWebComponent('neon-2_20_1-ai-chat-launcher', AiChatLauncher, aiChatLauncherDependencies);
